};

console.log(flattenObject(objjjj));
// { 'a.b.c': 10, d: 20 }

// Deep clone an object
const deepClone = (obj) => {
  if (obj === null || typeof obj !== "object") {
    return obj;
  }

  const copy = Array.isArray(obj) ? [] : {};

  for (let key in obj) {
    // Recursively clone every nested value
    copy[key] = deepClone(obj[key]);
  }

  return copy;
};

