// Check deep equality of two objects
const deepEqual = (obj1, obj2) => {
  // Same reference or same primitive value
  if (obj1 === obj2) {
    return true;
  }

  if (
    typeof obj1 !== "object" ||
    typeof obj2 !== "object" ||
    obj1 === null ||
    obj2 === null
  ) {
    return false;
  }

  const key1 = Object.keys(obj1);
  const key2 = Object.keys(obj2);

  if (key1.length !== key2.length) {
    return false;
  }

  for (let key of key1) {
    // Recursively compare the value of the current key
    if (!deepEqual(obj1[key], obj2[key])) {
      return false;
    }
  }

  return true;
};

