// Find unique objects in array
const uniqueObj = (arr, key) => {
  const seen = {};
  const result = [];

  for (let obj of arr) {
    if (!seen[obj[key]]) {
      seen[obj[key]] = true;
      result.push(obj);
    }
  }

  return result;
};

