// Merge arrays of objects by id
const margeArrofObj = (arr1, arr2) => {
  const res = [];

  for (let obj1 of arr1) {
    const marged = { ...obj1 };

    for (let obj2 of arr2) {
      if (obj1.id === obj2.id) {
        // Copy every property from the matching object
        for (let key in obj2) {
          marged[key] = obj2[key];
        }
      }
    }

    res.push(marged);
  }

  return res;
};

